def check_constraints(A, B, JA, JB):
    N_prime = len(JA) + len(JB)
    S1 = sum(j * A if j in JA else j * B for j in range(1, N_prime + 1))
    S2 = sum(j * A**2 if j in JA else j * B**2 for j in range(1, N_prime + 1))

    # Check m=1
    if (S1 - 1)**0.5 == int((S1 - 1)**0.5):
        K1 = int((S1 - 1)**0.5)
        print(f"m=1: S1={S1}, K1={K1} (Success)")
    else:
        print(f"m=1: S1={S1} (Failure)")

    # Check m=2
    if (S2 - 1)**(1/3) == int((S2 - 1)**(1/3)):
        K2 = int((S2 - 1)**(1/3))
        print(f"m=2: S2={S2}, K2={K2} (Success)")
    else:
        print(f"m=2: S2={S2} (Failure)")

# Test A=1, B=2, N'=2. JA={1}, JB={2}
check_constraints(1, 2, {1}, {2})

# Test A=2, B=1, N'=2. JA={2}, JB={1}
check_constraints(2, 1, {2}, {1})

